import React, { Component } from 'react';
import {
    CButton, CCard, CCardBody, CCol, CContainer, CInput, CInputGroup,
    CInputGroupAppend, CInputGroupPrepend, CInputGroupText, CRow, CTextarea
} from '@coreui/react';
import MaterialReactTable from 'material-react-table';
import {
    requestHeaderPOSTWithAuth,
    requestHeaderPUTWithAuth,
} from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';

const FILE_NAME = "Tenant.js";

// Create   : POST /v1/tenant
// Update   : PUT  /v1/tenant/{id}
// List/find: POST /v1/tenants  { page, size, search }
const API_ROOT = BACKEND_NEXUS_APP_BASE_URL + '/v1';
const CREATE_URL = API_ROOT + '/tenant';
const LIST_URL = API_ROOT + '/tenants';

const emptyForm = {
    id: null,          // null => create mode, non-null => edit mode
    name: '',
    urn: '',
    baseDomains: [''], // one input per base domain; starts with a single empty row
    description: '',
    folder: '',        // optional per-tenant media root directory
};

class Tenant extends Component {

    constructor(props) {
        super(props);
        this.state = {
            isLoaded: false,
            tenantList: [],
            // free-text search across name / urn / base domain + pagination
            searchTerm: '',
            page: 1,
            size: 50,
            totalPages: 0,
            totalElements: 0,
            // add / edit form
            form: { ...emptyForm },
            formError: null,
            // modals
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
        };
    }

    componentDidMount() {
        document.title = "Tenants";
        this.loadAll();
    }

    // ---------- helpers ----------

    isEditing = () => this.state.form.id != null;

    nullIfBlank = (value) => {
        const trimmed = (value || '').trim();
        return trimmed === '' ? null : trimmed;
    }

    // Trim each base-domain row and drop the blank ones, ready for the payload.
    cleanBaseDomains = (rows) => (rows || [])
        .map(d => (d || '').trim())
        .filter(d => d.length > 0);

    // ---------- base-domain rows (one input each) ----------

    // Update the value of a single base-domain row by index.
    handleBaseDomainChange = (index, value) => {
        this.setState(prevState => {
            const baseDomains = [...prevState.form.baseDomains];
            baseDomains[index] = value;
            return { form: { ...prevState.form, baseDomains } };
        });
    }

    // Append a new empty base-domain row.
    addBaseDomainRow = () => {
        this.setState(prevState => ({
            form: { ...prevState.form, baseDomains: [...prevState.form.baseDomains, ''] },
        }));
    }

    // Remove a base-domain row by index; always keep at least one (blank) row.
    removeBaseDomainRow = (index) => {
        this.setState(prevState => {
            const baseDomains = prevState.form.baseDomains.filter((_, i) => i !== index);
            return { form: { ...prevState.form, baseDomains: baseDomains.length ? baseDomains : [''] } };
        });
    }

    // ---------- clipboard ----------

    pasteFromClipboard = (field) => {
        if (!navigator.clipboard || !navigator.clipboard.readText) {
            this.setState({ failureModalVisible: true });
            return;
        }
        navigator.clipboard.readText()
            .then(text => {
                Logger(FILE_NAME, "pasteFromClipboard", field, "text", text);
                this.handleFormChange(field, text);
            })
            .catch(error => {
                Logger(FILE_NAME, "pasteFromClipboard", field, "error", error);
                this.setState({ failureModalVisible: true });
            });
    }

    copyToClipboard = (value) => {
        const text = value == null ? '' : String(value);
        if (!navigator.clipboard || !navigator.clipboard.writeText) {
            this.setState({ failureModalVisible: true });
            return;
        }
        navigator.clipboard.writeText(text)
            .then(() => Logger(FILE_NAME, "copyToClipboard", "SUCCESS", "text", text))
            .catch(error => {
                Logger(FILE_NAME, "copyToClipboard", "ERROR", "error", error);
                this.setState({ failureModalVisible: true });
            });
    }

    handleUnauthorized = () => {
        this.setState({ loadingModalVisible: false, failureModalVisible: true });
        setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500);
    }

    // ---------- read: list + search ----------

    // Paginated free-text search (POST /v1/tenants with PaginatedSearchRequest).
    // The backend only applies the search filter when the term is >= 3 chars;
    // a blank/short term returns all tenants ordered by name, paginated.
    fetchList = () => {
        const { page, size, searchTerm } = this.state;
        const userData = getUserDataFromLocalStorage();
        const term = searchTerm ? searchTerm.trim() : '';
        const reqData = { page, size, search: term.length >= 3 ? term : null };

        Logger(FILE_NAME, "fetchList", "REQUEST", "reqData", reqData);
        this.setState({ isLoaded: false });

        fetch(LIST_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) return this.handleUnauthorized();
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "fetchList", "RESULT", "result", result);
            const pageData = (result && result.data) || {};
            this.setState({
                isLoaded: true,
                tenantList: pageData.content || [],
                totalPages: pageData.totalPages || 0,
                totalElements: pageData.totalElements != null ? pageData.totalElements : 0,
            });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchList", "ERROR", "error", error);
            this.setState({ isLoaded: true, failureModalVisible: true });
        });
    }

    // "List all / refresh" — reset to page 1 with an empty search term.
    loadAll = () => {
        this.setState({ searchTerm: '', page: 1 }, () => this.fetchList());
    }

    handleSearch = (event) => {
        if (event) event.preventDefault();
        this.setState({ page: 1 }, () => this.fetchList());
    }

    handlePrevPage = () => {
        if (this.state.page > 1) {
            this.setState({ page: this.state.page - 1 }, () => this.fetchList());
        }
    }

    handleNextPage = () => {
        if (this.state.page < this.state.totalPages) {
            this.setState({ page: this.state.page + 1 }, () => this.fetchList());
        }
    }

    // ---------- create / update ----------

    handleFormChange = (field, value) => {
        this.setState(prevState => ({ form: { ...prevState.form, [field]: value } }));
    }

    resetForm = () => {
        this.setState({ form: { ...emptyForm }, formError: null });
    }

    startEditing = (item) => {
        this.setState({
            form: {
                id: item.id,
                name: item.name || '',
                urn: item.urn || '',
                baseDomains: (Array.isArray(item.baseDomains) && item.baseDomains.length) ? [...item.baseDomains] : [''],
                description: item.description || '',
                folder: item.folder || '',
            },
            formError: null,
        });
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    handleSubmit = (event) => {
        event.preventDefault();
        const { form } = this.state;

        const name = (form.name || '').trim();
        const urn = (form.urn || '').trim();
        if (name === '') {
            this.setState({ formError: 'Name is required.' });
            return;
        }
        if (urn === '') {
            this.setState({ formError: 'URN is required.' });
            return;
        }

        const payload = {
            name,
            urn,
            baseDomains: this.cleanBaseDomains(form.baseDomains),
            description: this.nullIfBlank(form.description),
            folder: this.nullIfBlank(form.folder),
        };

        const editing = this.isEditing();
        let url = CREATE_URL;
        let requestOptions = requestHeaderPOSTWithAuth(JSON.stringify(payload), getUserDataFromLocalStorage().authToken);
        if (editing) {
            url = CREATE_URL + '/' + form.id;   // PUT /v1/tenant/{id}
            requestOptions = requestHeaderPUTWithAuth(JSON.stringify(payload), getUserDataFromLocalStorage().authToken);
        }

        Logger(FILE_NAME, "handleSubmit", editing ? "UPDATE" : "CREATE", "request", { url, payload });
        this.setState({ formError: null, loadingModalVisible: true, loadingModalState: 0 });

        fetch(url, requestOptions)
        .then(response => response.json().then(body => ({ status: response.status, body })))
        .then(({ status, body }) => {
            Logger(FILE_NAME, "handleSubmit", "RESULT", "result", { status, body });
            if (status === 401) return this.handleUnauthorized();

            // Success: controller returns HTTP 200 with the saved tenant in `data`.
            if (status === 200 && body && body.data) {
                this.setState({ loadingModalState: 1 });
                setTimeout(() => {
                    this.setState({ loadingModalVisible: false, loadingModalState: 0 });
                    this.resetForm();
                    this.loadAll();
                }, 600);
                return;
            }

            // Business/validation error: RestExceptionHandler returns 400 with `errorMessage`.
            const message = (body && (body.errorMessage || body.message)) || 'Save failed (backend rejected the request).';
            this.setState({ loadingModalVisible: false, loadingModalState: 0, formError: message });
        })
        .catch(error => {
            Logger(FILE_NAME, "handleSubmit", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    // ---------- render ----------

    renderCopyButton = (value) => (
        <CButton
            color="link"
            size="sm"
            className="p-0 ml-1"
            title="Copy to clipboard"
            style={{ verticalAlign: 'baseline' }}
            onClick={() => this.copyToClipboard(value)}
        >
            📋
        </CButton>
    )

    getColumns = () => ([
        {
            accessorKey: 'id',
            header: 'ID',
            size: 70,
        },
        {
            accessorKey: 'name',
            header: 'Name',
            size: 200,
            Cell: ({ row }) => (
                row.original.name
                    ? <span>{row.original.name}{this.renderCopyButton(row.original.name)}</span>
                    : '—'
            ),
        },
        {
            accessorKey: 'urn',
            header: 'URN',
            size: 200,
            Cell: ({ row }) => (
                row.original.urn
                    ? <span style={{ wordBreak: 'break-all' }}>{row.original.urn}{this.renderCopyButton(row.original.urn)}</span>
                    : '—'
            ),
        },
        {
            accessorKey: 'baseDomains',
            header: 'Base Domains',
            size: 240,
            enableSorting: false,
            Cell: ({ row }) => {
                const domains = row.original.baseDomains;
                if (!Array.isArray(domains) || domains.length === 0) return '—';
                return (
                    <span style={{ wordBreak: 'break-all' }}>
                        {domains.join(', ')}
                        {this.renderCopyButton(domains.join(', '))}
                    </span>
                );
            },
        },
        {
            accessorKey: 'description',
            header: 'Description',
            size: 240,
            Cell: ({ row }) => (
                row.original.description
                    ? <span>{row.original.description}</span>
                    : '—'
            ),
        },
        {
            accessorKey: 'folder',
            header: 'Folder',
            size: 220,
            Cell: ({ row }) => (
                row.original.folder
                    ? <span style={{ wordBreak: 'break-all' }}>{row.original.folder}{this.renderCopyButton(row.original.folder)}</span>
                    : '—'
            ),
        },
        {
            accessorKey: 'uuid',
            header: 'UUID',
            size: 200,
            Cell: ({ row }) => (
                row.original.uuid
                    ? <span style={{ wordBreak: 'break-all' }}>{row.original.uuid}{this.renderCopyButton(row.original.uuid)}</span>
                    : '—'
            ),
        },
        {
            accessorKey: 'actions',
            header: 'Actions',
            size: 110,
            enableSorting: false,
            enableColumnFilter: false,
            Cell: ({ row }) => (
                <span style={{ whiteSpace: 'nowrap' }}>
                    <CButton color="primary" size="sm" onClick={() => this.startEditing(row.original)}>✏️ Edit</CButton>
                </span>
            ),
        },
    ])

    render() {
        const { isLoaded, tenantList, form, searchTerm } = this.state;
        const editing = this.isEditing();

        return (
            <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
                    <h2>🏢 Tenants ({this.state.totalElements})</h2>
                    <CButton color="secondary" onClick={this.loadAll} title="Refresh / List all">🔄 List all</CButton>
                </div>

                {/* ---------- Add / Edit form ---------- */}
                <CContainer className="mb-4">
                    <CCard className="p-3">
                        <CCardBody>
                            <h4>{editing ? '✏️ Edit Tenant #' + form.id : '➕ Add Tenant'}</h4>
                            <hr />
                            {this.state.formError && (
                                <div style={{ padding: '10px 14px', marginBottom: '14px', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', borderRadius: '4px', color: '#721c24' }}>
                                    ⚠️ {this.state.formError}
                                </div>
                            )}
                            <form onSubmit={this.handleSubmit}>
                                <CRow>
                                    <CCol md="6">
                                        <label><strong>Name *</strong></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>🏢</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="Acme Corp"
                                                type="text"
                                                value={form.name}
                                                onChange={(e) => this.handleFormChange('name', e.target.value)}
                                                required
                                            />
                                            <CInputGroupAppend>
                                                <CButton color="info" type="button" title="Paste from clipboard" onClick={() => this.pasteFromClipboard('name')}>📋</CButton>
                                            </CInputGroupAppend>
                                        </CInputGroup>
                                    </CCol>
                                    <CCol md="6">
                                        <label><strong>URN *</strong></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>🔖</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="acme-corp"
                                                type="text"
                                                value={form.urn}
                                                onChange={(e) => this.handleFormChange('urn', e.target.value)}
                                                required
                                            />
                                            <CInputGroupAppend>
                                                <CButton color="info" type="button" title="Paste from clipboard" onClick={() => this.pasteFromClipboard('urn')}>📋</CButton>
                                            </CInputGroupAppend>
                                        </CInputGroup>
                                    </CCol>
                                </CRow>
                                <CRow>
                                    <CCol md="6">
                                        <label><strong>Base Domains</strong> <small className="text-muted">(one per input, no slashes)</small></label>
                                        {form.baseDomains.map((domain, index) => (
                                            <CInputGroup className="mb-2" key={index}>
                                                <CInputGroupPrepend>
                                                    <CInputGroupText>🌐</CInputGroupText>
                                                </CInputGroupPrepend>
                                                <CInput
                                                    placeholder="acme.com"
                                                    type="text"
                                                    value={domain}
                                                    onChange={(e) => this.handleBaseDomainChange(index, e.target.value)}
                                                />
                                                <CInputGroupAppend>
                                                    <CButton
                                                        color="danger"
                                                        type="button"
                                                        title="Remove this base domain"
                                                        onClick={() => this.removeBaseDomainRow(index)}
                                                    >
                                                        ✖
                                                    </CButton>
                                                </CInputGroupAppend>
                                            </CInputGroup>
                                        ))}
                                        <CButton color="info" size="sm" type="button" className="mb-3" onClick={this.addBaseDomainRow}>
                                            ➕ Add base domain
                                        </CButton>
                                    </CCol>
                                    <CCol md="6">
                                        <label><strong>Description</strong></label>
                                        <CTextarea
                                            className="mb-3"
                                            rows="3"
                                            placeholder="optional"
                                            value={form.description}
                                            onChange={(e) => this.handleFormChange('description', e.target.value)}
                                        />
                                    </CCol>
                                </CRow>
                                <CRow>
                                    <CCol md="6">
                                        <label><strong>Folder</strong> <small className="text-muted">(optional per-tenant media root directory)</small></label>
                                        <CInputGroup className="mb-3">
                                            <CInputGroupPrepend>
                                                <CInputGroupText>📁</CInputGroupText>
                                            </CInputGroupPrepend>
                                            <CInput
                                                placeholder="optional, e.g. /data/media/acme"
                                                type="text"
                                                value={form.folder}
                                                onChange={(e) => this.handleFormChange('folder', e.target.value)}
                                            />
                                            <CInputGroupAppend>
                                                <CButton color="info" type="button" title="Paste from clipboard" onClick={() => this.pasteFromClipboard('folder')}>📋</CButton>
                                            </CInputGroupAppend>
                                        </CInputGroup>
                                    </CCol>
                                </CRow>
                                <hr />
                                <div style={{ display: 'flex', gap: '12px' }}>
                                    <CButton color="success" type="submit" className="px-4">
                                        {editing ? '💾 Update' : '➕ Save'}
                                    </CButton>
                                    <CButton color="secondary" type="button" onClick={this.resetForm}>
                                        {editing ? 'Cancel edit' : 'Clear'}
                                    </CButton>
                                </div>
                            </form>
                        </CCardBody>
                    </CCard>
                </CContainer>

                {/* ---------- Search (free-text over name / urn / base domain) ---------- */}
                <CContainer className="mb-3">
                    <CCard className="p-3">
                        <CCardBody>
                            <h5>🔍 Search</h5>
                            <form onSubmit={this.handleSearch}>
                                <CRow className="align-items-end">
                                    <CCol md="9">
                                        <label>Search name, URN or base domain (min 3 chars)</label>
                                        <CInput
                                            type="text"
                                            placeholder="type to search across name / URN / base domain..."
                                            value={searchTerm}
                                            onChange={(e) => this.setState({ searchTerm: e.target.value })}
                                        />
                                    </CCol>
                                    <CCol md="3">
                                        <CButton color="primary" type="submit" className="mr-2">Search</CButton>
                                        <CButton color="secondary" type="button" onClick={this.loadAll}>Clear</CButton>
                                    </CCol>
                                </CRow>
                            </form>
                        </CCardBody>
                    </CCard>
                </CContainer>

                {/* ---------- Results table ---------- */}
                {!isLoaded ? <Loading /> : (
                    <>
                        <MaterialReactTable
                            initialState={{ density: 'compact' }}
                            columns={this.getColumns()}
                            data={tenantList}
                            enablePagination={false}
                            enableEditing={false}
                        />
                        <CContainer className="mt-3">
                            <CRow className="justify-content-center align-items-center">
                                <CCol md="6" className="text-center">
                                    <CButton color="secondary" disabled={this.state.page <= 1} onClick={this.handlePrevPage}>← Prev</CButton>
                                    &nbsp;&nbsp;
                                    <span>
                                        Page <strong>{this.state.page}</strong> of <strong>{this.state.totalPages}</strong>
                                        &nbsp;({this.state.totalElements} total)
                                    </span>
                                    &nbsp;&nbsp;
                                    <CButton color="secondary" disabled={this.state.page >= this.state.totalPages} onClick={this.handleNextPage}>Next →</CButton>
                                </CCol>
                            </CRow>
                        </CContainer>
                    </>
                )}

                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }
}

export default Tenant;
